import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"泽地萃","description":"周易折中 - 泽地萃","frontmatter":{"title":"泽地萃","description":"周易折中 - 泽地萃"},"headers":[],"relativePath":"zh/classics/zhezhong/051.md","filePath":"zh/classics/zhezhong/051.md"}'),h={name:"zh/classics/zhezhong/051.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="泽地萃" tabindex="-1">泽地萃 <a class="header-anchor" href="#泽地萃" aria-label="Permalink to “泽地萃”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈萃序〉：“卦姤者，遇也。物相遇而后聚，故受之以萃。萃者，聚也。物相㑹遇，则成群萃，所以次姤也。为卦兑上坤下，泽上于地，水之聚也，故为萃。不言泽在地上，而云泽上于地，则为方聚之义也。”</p><p>萃：亨，王假有庙，利见大人，亨，利贞。用大牲吉，利有攸往</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>萃，聚也。坤顺兑说，九五刚中而二应之，又为泽上于地，万物萃聚之象，故为萃。亨字衍文。王假有庙，言王者可以至乎宗庙之中，王者卜祭之吉占也。《祭义》曰：“公假于太庙”是也。庙所以聚祖考之精神，又人必能聚己之精神，则可以至于庙而承祖考也。物既聚，则必见大人而后可以得亨。然又必利于正，所聚不正，则亦不能亨也。大牲必聚而后有，聚则可以有所往，皆占吉而有戒之辞。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>王者萃聚天下之道，至于有庙极也。群生至众也，而可一其归仰；人心莫知其乡也，而能致其诚敬；鬼神之不可度也，而能致其来格。天下萃合，人心总摄众志之道，非一其至大，莫过于宗庙。故王者萃天下之道，至于有庙，则萃道之至也。祭祀之报本于人心，圣人制礼以成其徳耳，故豺獭能祭，其性然也。萃下有亨字，羡文也。亨字自在下，与涣不同。涣则先言卦才，萃乃先言卦义。彖辞甚明，天下之聚，必得大人以治之。人聚则乱，物聚则争，事聚则紊，非大人治之，则萃所以致争乱也。萃以不正，则人聚为苟合，财聚为悖入，安得亨乎？故利贞。萃者，丰厚之时也，其用宜称，故用大牲吉。事莫重于祭，故以祭享而言。上交鬼神，下接民物，百用莫不皆然。当萃之时而交物以厚，则是享丰富之吉也。天下莫不同其富乐矣。若时之厚而交物以薄，乃不享其丰美，天下莫之与而悔吝生矣。盖随时之宜，顺理而行，故彖云“顺天命也”。夫不能有为者，力之不足也。当萃之时，故利有攸往。大凡兴工立事，贵得可为之时，萃而后用，是动而有裕，天理然也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>程子曰 ：萃、涣皆立庙，因其精神之萃而形于此，为其涣散，故立此以收之。</li></ul><p>程子曰 ：萃、涣皆立庙，因其精神之萃而形于此，为其涣散，故立此以收之。</p><ul><li>项氏安世曰 ：卦名下元无亨字，独王肃本有，王弼遂用其说，孔子彖辞初不及此字。</li></ul><p>项氏安世曰 ：卦名下元无亨字，独王肃本有，王弼遂用其说，孔子彖辞初不及此字。</p><ul><li>赵氏汝腾曰 ：阳居五而五阴从之，为比；阳居五与四，而四阴从之，为萃。二卦相似，然比者众阴始附之初，圣人作而万物睹之时也；萃者二阳相比，群阴萃而归之，君臣同德，万物盛多之时也。</li></ul><p>赵氏汝腾曰 ：阳居五而五阴从之，为比；阳居五与四，而四阴从之，为萃。二卦相似，然比者众阴始附之初，圣人作而万物睹之时也；萃者二阳相比，群阴萃而归之，君臣同德，万物盛多之时也。</p><ul><li>龚氏焕曰 ：假字疑当作“昭假”，烈祖之假谓感格也。王者致祭于宗庙，以己之精神感格祖考之精神，所以为萃也。</li></ul><p>龚氏焕曰 ：假字疑当作“昭假”，烈祖之假谓感格也。王者致祭于宗庙，以己之精神感格祖考之精神，所以为萃也。</p><ul><li>何氏楷曰 ：“用大牲吉”承“王假有庙”言，“利有攸往”承“利见大人”言。</li></ul><p>何氏楷曰 ：“用大牲吉”承“王假有庙”言，“利有攸往”承“利见大人”言。</p><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>以彖传观之，“利见大人、亨、利贞”为一事无疑。王假有庙者，神人之聚也；利见大人者，上下之聚也。用大牲吉，广言群祀；由假庙而推之，皆所以聚于神也。利有攸往，广言所行；由见大人而推之，皆所以聚于人也。</p><p>象曰：泽上于地萃，君子以除戎器，戒不虞</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>除者，脩而聚之之谓。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>泽上于地为萃聚之象。君子观萃象，以除治戎器，用戒备于不虞。凡物之萃，则有不虞度之事故；众聚则有争，物聚则有夺，大牵既聚则多故矣。故观萃象而戒也。除谓简治也，去弊恶也。除而聚之，所以戒不虞也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：聚而无防，则众生心。</p></li><li><p>朱子语类云：大凡物聚众盛处，必有争，故当豫为之备。又泽本当在地中，今却上于地上，是水盛有溃决奔突之忧，故取象如此。</p></li><li><p>王氏申子曰：泽上有地临则聚。泽者，地岸也。泽上于地萃则聚。泽者，堤防也。以地岸而聚泽，则无堤防之劳；以堤防而聚泽，则有溃决之忧。故君子观此象，为治世之防，除治其戎器，以为不虞之戒。若以治安而忘战守之备，则是以旧防为无用而壊之也，其可乎？</p></li></ul><p>彖曰：萃，聚也，顺以说，刚中而应，故聚也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦德、卦体释卦名义。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>萃之义聚也。顺以说，以卦才言也。上说而下顺，为上以说道使民而顺于人心，下说上之政令而顺从于上。既上下顺说，又阳刚处中正之位而下有应助，如此故能聚也。欲天下之萃才，非如是不能也。</p><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>顺以说、刚中而应，亦非正释卦名，乃就卦德而推原所以聚者，以起释辞之端也。盖顺以说是以顺道感格，起假庙用牲之意；刚中而应是有德者居位而上下应之，起见大人有攸往之意。</p><p>王假有庙，致孝享也；利见大人，亨，聚以正也；用大牲，吉利有攸往，顺天命也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>释卦辞。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>王者萃人心之道，至于建立宗庙，所以致其孝享之诚也。祭祀人心之所自尽也，故萃天下之心者无如孝享。王者萃天下之道，至于有庙，则其极也。萃之时见大人，则能亨，盖聚以正道也。见大人则其聚以正道，得其正则亨矣。萃不以正，其能亨乎？用大牲承上有庙之文，以享祀而言。凡事莫不如是，丰聚之时交于物者当厚，称其宜也。物聚而力瞻，乃可以有为，故利有攸往。皆天理然也，故云顺天命也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>来氏知德曰 ：尽志以致其孝，尽物以致其享。</li></ul><p>观其所聚，而天地万物之情可见矣</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>极言其理而赞之。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>观萃之理，可以见天地万物之情也。天地之化育，万物之生成，凡有者皆聚也。有无、动静、终始之理，聚散而已。故观其所以聚，则天地万物之情可见矣。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：方以类聚，物以群分，情同而后乃聚，气合而后乃群。</p></li><li><p>胡氏炳文曰 ：咸之情通，恒之情久，聚之情一。然其所以感、所以恒、所以聚，则皆有理存焉。如天地圣人之感，感之理也；如日月之得天、圣人之久于道，恒之理也；萃之聚以正，所谓顺天命，聚之理也。凡天地万物之可见者，皆此理之可见矣。故本义于所感则曰极言感通之理，于所恒则曰极言恒久之道，于所聚亦曰极言其理而赞之。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>顺天命虽系于“用大牲，利有攸往”之下，然连“假庙见大人”之意皆在其中矣。盖万物本乎天，人本乎祖，方以类聚，物以群分。圣人作而万物睹，是乃天地人物之所以联属而不散者，实天之命也。咸、恒皆推言造化人事，而后终之以天地万物之情可见。此卦则天人之义已备，故言顺天命而遂极赞之。</p><p>初六：有孚不终，乃乱乃萃，若号一握为笑，勿恤，往无咎</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>初六上应九四而隔于二阴，当萃之时不能自守，是有孚而不终，志乱而妄聚也。若呼号正应，则众以为笑，但勿恤而往从正应，则无咎矣。戒占者当如是也。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>初与四为正应，本有孚以相从者也。然当萃时，三阴聚处，柔无守正之节，若舍正应而从其类，乃有孚而不终也。乃乱，惑乱其心也；乃萃，与其同类聚也。初若守正不从，号呼以求正应，则一握笑之矣。一握，俗语，一圑也，谓众以为笑也。若能勿恤而往从刚阳之正应，则无过咎，不然则入小人之群矣。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏瑗曰 ：号谓号啕也。萃聚之世，必上下相求和会，然后必有所济。故始有号啕之怨，终得与四萃聚而有欢笑也。</li></ul><p>胡氏瑗曰 ：号谓号啕也。萃聚之世，必上下相求和会，然后必有所济。故始有号啕之怨，终得与四萃聚而有欢笑也。</p><ul><li>王氏宗传曰 ：初之于四，相信之志疑乱而不一也。然居萃之时，上下相求，若号焉，四必说而应之，则一握之顷，变号啕而为笑乐矣。谓得其所萃也。故戒之曰“勿恤”，又勉之曰“往无咎”。</li></ul><p>王氏宗传曰 ：初之于四，相信之志疑乱而不一也。然居萃之时，上下相求，若号焉，四必说而应之，则一握之顷，变号啕而为笑乐矣。谓得其所萃也。故戒之曰“勿恤”，又勉之曰“往无咎”。</p><ul><li>姚氏舜牧曰 ：初四相应，此心本自相孚，但孚须有终为善。如有孚而不终，则乃乱而乃萃矣。萃其可乱乎哉？若念有孚之当终而呼号以往从之，则正应可合而无妄萃之咎矣。</li></ul><p>姚氏舜牧曰 ：初四相应，此心本自相孚，但孚须有终为善。如有孚而不终，则乃乱而乃萃矣。萃其可乱乎哉？若念有孚之当终而呼号以往从之，则正应可合而无妄萃之咎矣。</p><ul><li>钱氏志立曰 ：萃与比同，所异者多九四一阳耳。比初无应，曰“有孚者一于五也”；萃初与四应，曰“有孚不终者”，有二阳焉，不终于四也。及此时而号以求萃，可以破涕为笑，同人先号啕而后笑者是也。</li></ul><p>钱氏志立曰 ：萃与比同，所异者多九四一阳耳。比初无应，曰“有孚者一于五也”；萃初与四应，曰“有孚不终者”，有二阳焉，不终于四也。及此时而号以求萃，可以破涕为笑，同人先号啕而后笑者是也。</p><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>胡氏、王氏、姚氏、钱氏诸说皆于文义甚合。盖易中“号”、“笑”二字每每相对也。两“乃”字不同，上“乃”字虚字也，下“乃”字犹“汝”也，正如“书而康而色”，“上而”字虚字也，下“而”字犹“汝”也。言有孚不终，则必乱，“汝”之所萃也。其所以乱之故，则钱氏得之矣。握者，手所执持，以转移之机也。言能致诚迫切，则一转移之闲，必有和合之喜，故曰“若号一握为笑”。</p><p>象曰：乃乱乃萃，其志乱也</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>其心志为同类所惑乱，故乃萃于群阴也，不能固其守，则为小人所惑乱而失其正矣。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>李氏简曰：非其志惑乱，必无舍应乱萃之理。</li></ul><p>六二：引吉无咎，孚乃利用禴</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>二应五而杂于二阴之闲，必牵引以萃，乃吉而无咎。又二中正柔顺，虚中以上应九五刚健中正诚实，而下交，故卜祭者有其孚诚，则虽薄物亦可以祭矣。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>初阴柔又非中正，恐不能终其孚，故因其才而为之戒。二虽阴柔而得中正，故虽戒而微辞。凡爻之辞关得失二端者，为法为戒亦各随其才而设也。引吉无咎，引者相牵也。人之交相求则合，相待则离。二与五为正应，当萃者也，而相远又在群阴之闲，必相牵引则得其萃矣。五居尊位，有中正之德，二亦以中正之道往与之萃，乃君臣和合也。其所共致岂可量也，是以吉而无咎也。无咎者，善补过也。二与五不相引则过矣。孚乃利用禴，孚信之在中，诚之谓也。禴祭之简薄者也，菲薄而祭，不尚备物，直以诚意交于神明也。孚乃者，谓有其孚则可不用文饰，专以至诚交于上也。以禴言者，谓荐其诚而已，上下相聚而尚饰焉，是未诚也。盖其中实者不假饰于外，用禴之义也。孚信者，萃之本也，不独君臣之聚，凡天下之聚在诚而已。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏瑗曰 ：君子之进，不可自媒以苟媚其君而幸其时之宠荣也。是故君子进用，必须有道。六二以阴居阴，履得其中，又上应九五中正之君，必待其君援引于己，然后往之，此所以得吉而无咎也。孚，信也；禴，薄祭也。君子之进，必在乎诚信相交，心志相接。当萃聚之时，诚信既著，心志既通，则可以不烦外饰，其道得行矣。孚信中立，则虽禴之薄祭，亦可通于神明也。</li></ul><p>胡氏瑗曰 ：君子之进，不可自媒以苟媚其君而幸其时之宠荣也。是故君子进用，必须有道。六二以阴居阴，履得其中，又上应九五中正之君，必待其君援引于己，然后往之，此所以得吉而无咎也。孚，信也；禴，薄祭也。君子之进，必在乎诚信相交，心志相接。当萃聚之时，诚信既著，心志既通，则可以不烦外饰，其道得行矣。孚信中立，则虽禴之薄祭，亦可通于神明也。</p><ul><li>张子曰 ：能自持不变，引而后往，吉乃无咎。凡言“利用禴”，皆诚素著白于幽明之际。</li></ul><p>张子曰 ：能自持不变，引而后往，吉乃无咎。凡言“利用禴”，皆诚素著白于幽明之际。</p><ul><li>王氏宗传曰 ：彖以用大牲为吉，而六二以用禴为利，何也？备物者，王者所以随其时；有孚者，人臣所以通乎上。</li></ul><p>王氏宗传曰 ：彖以用大牲为吉，而六二以用禴为利，何也？备物者，王者所以随其时；有孚者，人臣所以通乎上。</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>彖言“利见大人”，九五者，卦之大人也。六二应之，得见大人之义矣。然见大人者，聚必以正，故必待其引而从之，乃吉而无咎。盖聚而不正则不亨也。“孚乃利用禴”者，言相聚之道以诚为本，苟有明信，虽用禴可祭矣，况大牲乎？亦根卦义而反其辞也。《易》曰“可用汲”，王明并受其福。传曰“在下位不援上”，此“引”字是汲引之引，非援引之引。</p><p>象曰：引吉无咎，中未变也</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>萃之时，以得聚为吉。故九四为得上下之萃。二与五虽正应，然异处有闲，乃当萃而未合者也。故能相引而萃，则吉而无咎。以其有中正之德，未遽至改变也。变则不相引矣。或曰：“二既有中正之德，而象云未变，辞若不足何也？”曰：“群阴比处，乃其类聚方萃之时。居其闲，能自守不变，远须正应。刚立者能之，二阴柔之才，以其有中正之德，可觊其未至于变耳。故象含其意，以存戒也。”</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>杨氏万里曰：中未变者，盖六二所守之中道，不以为上所引而有所变也。</li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>此“中未变”与“比”卦中“二不自失”之意同，即《中庸》所谓“不变塞焉”，孟子所谓“达不离道”者是也。</p><p>六三：萃如嗟如，无攸利，往无咎，小吝</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>六三阴柔不中不正，上无应与，欲求萃于近而不得，故嗟如而无所利。唯往从于上可以无咎，然不得其萃，困然后往复，得阴极无位之爻，亦小可羞矣。戒占者当近舍不正之强援，而远结正应之穷交，则无咎也。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>三，阴柔不中正之人也。求萃于人而人莫与，求四则非其正应，又非其类，是以不正为四所弃也。与二则二自以中正应五，是以不正为二所不与也。故欲萃如，则为人弃绝而嗟如，不获萃而嗟恨也。上下皆不与，无所利也。唯往而从上六，则得其萃，为无咎也。三与上虽非阴阳正应，然萃之时，以类相从，皆以柔居一体之上，又皆无与居相应之地，上复处说顺之极，故得其萃而无咎也。易道变动无常，在人识之。然而小吝何也？三始求萃于四与二不获，而后往从上六，人之动为如此，虽得所求，亦可小羞吝也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>吴氏澄曰 ：与二阴萃于下而上无应，故嗟叹不得志。虽无应而比近九四之阳，苟能往而上求九四，则可无咎。</li></ul><p>吴氏澄曰 ：与二阴萃于下而上无应，故嗟叹不得志。虽无应而比近九四之阳，苟能往而上求九四，则可无咎。</p><ul><li>俞氏琰曰 ：萃之时，利见大人。三与五非应非比，而不得其萃，未免有嗟叹之声，则无攸利矣。既曰无攸利，又曰往无咎。三与四比，则其往也，舍四可乎？三之从四，四亦巽而受之，故无咎。第无正应而近比于四，所聚非正，有此小疵耳。</li></ul><p>俞氏琰曰 ：萃之时，利见大人。三与五非应非比，而不得其萃，未免有嗟叹之声，则无攸利矣。既曰无攸利，又曰往无咎。三与四比，则其往也，舍四可乎？三之从四，四亦巽而受之，故无咎。第无正应而近比于四，所聚非正，有此小疵耳。</p><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>以《象传》观之，吴氏、俞氏之说是也。易例中，三四隔体无相从之义，然亦有以时义而相从者，如《随》三之系丈夫及此爻是也。其不正而亦以时义相从者，《豫》三、《咸》三是也，皆因九四有主卦之义者故然。</p><p>象曰：往无咎，上巽也</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>上居柔，说之极。三往而无咎者，上六巽顺而受之也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰：动之四，故上巽。</p></li><li><p>郑氏汝谐曰：下二阴皆萃于阳矣，三独无附，故咨嗟怨叹而无攸利。虽然，当萃之时，下欲萃于上，上亦欲下之萃于我。三不以无应之故，能往归于上，虽小吝而亦可以无咎。上非上六，谓在上之阳也。</p></li></ul><p>九四：大吉，无咎</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>上比九五，下比众阴，得其萃矣。然以阳居阴，不正，故戒占者必大吉，然后得无咎也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>四当萃之时，上比九五之君，得君臣之聚也；下比下体萃阴，得下民之聚也。得上下之聚，可谓善矣。然四以阳居阴，非正也。虽得上下之聚，必得大吉，然后为无咎也。大为周遍之义，无所不周然后为大，无所不正则为大吉。大吉则无咎也。夫上下之聚，固有不由正道而得者，非理枉道而得君者，自古多矣；非理枉道而得民者，盖亦有焉。如齐之陈恒、鲁之季氏是也。然得为大吉乎？得为无咎乎？故九四必能大吉，然后为无咎也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>房氏乔曰 ：大吉，谓匪躬尽瘁，始终无玷，可免专民之咎。有谓立大功可免咎者，非也。</li></ul><p>房氏乔曰 ：大吉，谓匪躬尽瘁，始终无玷，可免专民之咎。有谓立大功可免咎者，非也。</p><ul><li>项氏安世曰 ：无尊位而得众心，故必大吉而后可以无咎。如《益》之初九，在下位而任厚事，亦必元吉而后可以无咎也。</li></ul><p>项氏安世曰 ：无尊位而得众心，故必大吉而后可以无咎。如《益》之初九，在下位而任厚事，亦必元吉而后可以无咎也。</p><ul><li>胡氏炳文曰 ：《比》卦五阴皆比五之一阳，萃四阴皆聚归五与四之二阳。五曰“萃有位”，以见四之萃非有位也。无尊位而得众心，非大吉安能无咎。</li></ul><p>胡氏炳文曰 ：《比》卦五阴皆比五之一阳，萃四阴皆聚归五与四之二阳。五曰“萃有位”，以见四之萃非有位也。无尊位而得众心，非大吉安能无咎。</p><p>象曰：大吉无咎，位不当也</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>以其位之不当，疑其所为未能尽善，故云必得大吉然后为无咎也。非尽善安得为大吉乎？</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰：非其位而有聚物之权，非大吉则有咎矣。</p></li><li><p>郭氏雍曰：四得上下之聚，而非君位，故言不当也。</p></li><li><p>郑氏汝谐曰：其位近，其德同，其为下之所归亦同。自非所为至善，则其君病之，乌能无咎？戒之也。凡言位不当，其义不一，此所谓不当者，为其以刚阳迫近其君也。</p></li><li><p>熊氏良辅曰：九四九五皆萃之主，九五在上之萃也，九四在下之萃也。故九五曰萃有位，而四象曰位不当。大吉无咎者，上比于君，以臣而有君萃之象，疑于有咎故也。</p></li></ul><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>郑氏谓凡言位不当，其义不一者，是已然。须知是借爻位之当不当，以发明其德与时位之当不当。</p><p>九五：萃有位，无咎，匪孚，元永贞，悔亡</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>九五刚阳中正，当萃之时而居尊，固无咎矣。若有未信，则亦修其元永贞之德而悔亡矣。戒占者当如是也。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>九五居天下之尊，萃天下之众而君临之，当正其位，修其德。以阳刚居尊位，称其位矣，为有其位矣。得中正之道，无过咎也。如是而有不信而未归者，则当自反以修其元永贞之德，则无思不服而悔亡矣。元永贞者，君之德，民所归也。故比天下之道与萃天下之道，皆在此三者。王者既有其位，又有其德，中正无过咎，而天下尚有未信服归附者，盖其道未光大也。元永贞之道未至也，在修德以来之，如苗民逆命，帝乃诞敷文德。舜德非不至也，盖有远近昏明之异，故其归有先后。既有未归，则当修德也。所谓德元永贞之道也。元首也长也，为君德首出庶物，君长群生，有尊大之义焉，有主统之义焉。而又恒永贞固，则通于神明，光于四海，无思不服矣。乃无匪孚，而其悔亡也。所谓悔，志之未光，心之未慊也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏宗传曰 ：五萃之主也。当萃之时，为萃之主，莫大于有其位，尤莫大于有其道。有是位而无是道，则天下不我信者亦众矣。故曰“匪孚”，谓天下之人容有言曰：“上之人但以位而萃我也，而其道则未至也。”故必元永贞而后悔亡。</li></ul><p>王氏宗传曰 ：五萃之主也。当萃之时，为萃之主，莫大于有其位，尤莫大于有其道。有是位而无是道，则天下不我信者亦众矣。故曰“匪孚”，谓天下之人容有言曰：“上之人但以位而萃我也，而其道则未至也。”故必元永贞而后悔亡。</p><ul><li>朱子语类问 ：九五以阳刚中正当萃之时而居尊位，安得又有匪孚？曰：此言有位而无德，则虽萃而不能使人信。故人有不信，当修其元永贞之德而后悔亡也。案：萃九五居尊以萃群阴，与比略同。卦象泽上于地，与比象亦略同也，故其元永贞之辞亦同。元永贞悔亡，即所谓原筮元永贞无咎也。</li></ul><p>朱子语类问 ：九五以阳刚中正当萃之时而居尊位，安得又有匪孚？曰：此言有位而无德，则虽萃而不能使人信。故人有不信，当修其元永贞之德而后悔亡也。案：萃九五居尊以萃群阴，与比略同。卦象泽上于地，与比象亦略同也，故其元永贞之辞亦同。元永贞悔亡，即所谓原筮元永贞无咎也。</p><p>象曰：萃有位，志未光也</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>未光谓匪孚。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>象举爻上句，王者之志必欲诚信着于天下，有感必通。含生之类，莫不怀归。若尚有匪孚，是其志之未光大也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>龚氏焕曰：五有其位者也，徒有其位，故人或匪孚，此志之所以未光也。</p></li><li><p>胡氏炳文曰：四必大吉而后无咎，位不当也。五有位矣，而匪孚，志犹未光也。然则欲当天下之萃者，不可无其位，有其位又不可无其德。</p></li></ul><p>上六：赍咨涕洟，无咎</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>处萃之终，阴柔无位，求萃不得，故戒占者必如此而后可以无咎也。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>六说之主，阴柔小人，说高位而处之，天下孰肯与也？求萃而人莫之与，其穷至于赍咨而涕洟也。赍咨，咨嗟也。人之绝之，由已自取，又将谁咎？为人恶绝，不知所为，则陨获而至嗟涕，真小人之情状也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li>方氏应祥曰 ：此爻照后夫凶看。比之上六以比之最后而凶，萃之上六亦以萃之最后而有未安者，故其忧惧若此。此正所谓孤臣孽子也。</li></ul><p>方氏应祥曰 ：此爻照后夫凶看。比之上六以比之最后而凶，萃之上六亦以萃之最后而有未安者，故其忧惧若此。此正所谓孤臣孽子也。</p><ul><li>黄氏淳耀曰 ：上乃孤孽之臣子也。萃极将散而不得所萃，乃不得于君亲者。赍咨涕洟四字，乃极言怨艾求萃之情，故终得萃而无咎。</li></ul><p>黄氏淳耀曰 ：上乃孤孽之臣子也。萃极将散而不得所萃，乃不得于君亲者。赍咨涕洟四字，乃极言怨艾求萃之情，故终得萃而无咎。</p><h3 id="案-8" tabindex="-1">案 <a class="header-anchor" href="#案-8" aria-label="Permalink to “案”">​</a></h3><p>方氏、黄氏之说得之。盖不止孤臣孽子，乃放臣、屏子之伦也。方氏以比上相照，亦是然。比上直曰凶，此则赍咨涕洟而无咎者。比彖有“后夫凶”之辞，故遂以上六当之。此彖有“利见大人”之辞，正与蹇卦同例，故尚有积诚求萃之理也。</p><p>象曰：赍咨涕洟，未安上也</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>小人所处常失其宜，既贪而从欲，不能自择安地。至于困穷，则顚沛不知所为。六之涕洟，盖不安于处上也。君子愼其所处，非义不居。不幸而有危困，则泰然自安，不以累其心。小人居不择安，常履非据，及其穷迫，则陨获躁挠，甚至涕洟，为可羞也。未者，非遽之辞，犹俗云“未便”也，未便能安于上也。阴而居上，孤处无与，既非其据，岂能安乎？</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li>赵氏光大曰：言危惧而不敢自安于上，操心危虑患深，安得晏然而已乎？</li></ul><h3 id="案-9" tabindex="-1">案 <a class="header-anchor" href="#案-9" aria-label="Permalink to “案”">​</a></h3><p>上犹外也，虽在外而不敢自安，如舜之耕历山，周公之处东国，必号泣哓哓，求萃于君父而后已也。</p>',165)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
